CREATE OR REPLACE FUNCTION public.touch_profile() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at=now(); IF NEW.consent_at IS NOT NULL AND (btrim(NEW.first_name)='' OR btrim(NEW.last_name)='' OR cardinality(NEW.intentions)=0 OR NEW.linkedin_url !~* '^https://(www\.)?linkedin\.com/in/[^/?#]+/?$') THEN RAISE EXCEPTION 'Invalid completed profile'; END IF; RETURN NEW; END $$;